(()=>{'use strict';
const KEY='paper-adventure-demo-v1';
const initial={name:'林雾',age:27,occupation:'古物学者',stats:{STR:45,CON:55,SIZ:50,DEX:65,APP:60,POW:65,INT:75,EDU:65},resources:{hp:10,mp:13,san:65},maxResources:{hp:10,mp:13,san:65},skills:[{name:'侦查',type:'调查',value:65},{name:'图书馆使用',type:'知识',value:70},{name:'历史',type:'知识',value:60},{name:'聆听',type:'调查',value:45},{name:'话术',type:'社交',value:40},{name:'急救',type:'实用',value:35}],backstory:'父亲留下的地图上，有一座不在任何书里出现的小镇。\n我决定沿着那条褪色的河，亲眼去看一看。',significantPeople:'父亲，一位失踪的地图绘制者',traits:['好奇心旺盛','过目不忘'],gear:[0,1],favorites:[],moduleOrder:['identity','stats','resources','skills','story','inventory'],enabledModules:['identity','stats','resources','skills','story','inventory']};
let s=structuredClone(initial);try{let saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.stats&&saved.skills)s={...s,...saved};}catch{}
const variants=window.VARIANTS.sort((a,b)=>a.id-b.id);let current=Math.min(10,Math.max(1,Number(new URLSearchParams(location.search).get('v'))||1));let lastRoll={name:'幸运检定',value:50};let toastTimer;
const $=q=>document.querySelector(q),all=q=>[...document.querySelectorAll(q)],C=()=>window.createComponents(s),esc=v=>C().escape(v);
const moduleNames={identity:'身份与职业',stats:'八项属性',resources:'生命与状态',skills:'技能与检定',story:'角色故事',inventory:'随身行囊'};
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));$('#save-status').textContent='已保存至此浏览器';}catch{$('#save-status').textContent='当前修改仅保留在此页面';}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function occupationPoints(){return s.occupation==='私家侦探'?s.stats.EDU*2+s.stats.DEX*2:s.occupation==='旅行记者'?s.stats.EDU*2+s.stats.APP*2:s.stats.EDU*4;}
function derived(){let total=Object.values(s.stats).reduce((a,b)=>a+b,0);all('[data-derived="total"]').forEach(e=>e.textContent=total);all('[data-derived="budget-note"]').forEach(e=>{e.textContent=total===480?'已分配完成':total<480?`剩余 ${480-total} 点`:`超出 ${total-480} 点`;e.classList.toggle('over-budget',total>480)});all('[data-derived="interest"]').forEach(e=>e.textContent=s.stats.INT*2);all('[data-derived="occupation"]').forEach(e=>e.textContent=occupationPoints());let max={hp:Math.floor((s.stats.CON+s.stats.SIZ)/10),mp:Math.floor(s.stats.POW/5),san:s.stats.POW};Object.keys(max).forEach(k=>{if(s.resources[k]===s.maxResources[k])s.resources[k]=max[k];s.maxResources[k]=max[k];s.resources[k]=Math.min(s.resources[k],max[k]);});updateResources();}
function updateResources(){Object.keys(s.resources).forEach(k=>{all(`[data-resource-value="${k}"]`).forEach(e=>e.textContent=`${s.resources[k]} / ${s.maxResources[k]}`);all(`[data-resource-fill="${k}"]`).forEach(e=>e.style.width=`${100*s.resources[k]/Math.max(1,s.maxResources[k])}%`);});}
function nav(){let en=['FIELD BOOK','POCKET DOSSIER','HERBARIUM','TRAIL MAP','GUILD REGISTER','ARCANE FOLIO','SCRAPBOOK','SEA JOURNAL','NIGHT INQUIRY','ASSEMBLY DESK'];$('#variant-nav').innerHTML=variants.map(v=>`<button class="variant-button ${current===v.id?'active':''} ${s.favorites.includes(v.id)?'favorite':''}" data-action="variant" data-variant="${v.id}" ${current===v.id?'aria-current="page"':''}><span class="nav-number">${String(v.id).padStart(2,'0')}</span><span class="nav-title">${esc(v.name)}<small class="nav-sub">${en[v.id-1]}</small></span></button>`).join('');}
function render(){let same=$('#demo-stage').querySelector('.variant-'+current),journey=same?.querySelector('[data-journey-panel]:not([hidden])')?.dataset.journeyPanel,opened=same?[...same.querySelectorAll('details')].map(d=>d.open):[],searches=same?[...same.querySelectorAll('.skill-search')].map(x=>x.value):[];let v=variants.find(v=>v.id===current)||variants[0];current=v.id;$('#edition').textContent=`STUDY ${String(v.id).padStart(2,'0')} / ${v.en}`;$('#variant-title').textContent=v.name;$('#variant-description').textContent=v.desc;$('#page-count').textContent=`${String(v.id).padStart(2,'0')} / 10`;$('#demo-stage').innerHTML=v.render(C(),s);$('#favorite-button').textContent=s.favorites.includes(current)?'★ 已收藏':'☆ 收藏方向';$('#favorite-button').setAttribute('aria-pressed',s.favorites.includes(current));nav();derived();if(journey){all('[data-journey-panel]').forEach(p=>p.hidden=p.dataset.journeyPanel!==journey);all('[data-action="journey"]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.step===journey));}if(same){all('#demo-stage details').forEach((d,i)=>d.open=opened[i]??d.open);all('.skill-search').forEach((x,i)=>{x.value=searches[i]||'';x.dispatchEvent(new Event('input',{bubbles:true}));});}document.title=`${v.name} · 纸上冒险`;}
function choose(id){current=id;let u=new URL(location.href);u.searchParams.set('v',id);history.replaceState(null,'',u);render();all('dialog[open]').forEach(d=>d.close());window.scrollTo({top:0,behavior:'instant'});}
function overview(){$('#overview-grid').innerHTML=variants.map(v=>`<button class="overview-card" data-action="variant" data-variant="${v.id}"><div class="mini-preview" style="--tone:${v.color}"><span>${String(v.id).padStart(2,'0')}</span></div><strong>${esc(v.name)} ${s.favorites.includes(v.id)?'★':''}</strong><small>${esc(v.en)}</small></button>`).join('');$('#overview-dialog').showModal();}
function moduleRows(){$('#module-list').innerHTML=s.moduleOrder.map((m,i)=>`<div class="module-row"><label><input type="checkbox" data-module-toggle="${m}" ${s.enabledModules.includes(m)?'checked':''}>${moduleNames[m]}</label><button data-action="move-module" data-module="${m}" data-direction="up" aria-label="上移${moduleNames[m]}" ${i===0?'disabled':''}>↑</button><button data-action="move-module" data-module="${m}" data-direction="down" aria-label="下移${moduleNames[m]}" ${i===s.moduleOrder.length-1?'disabled':''}>↓</button></div>`).join('');}
function roll(name,value){lastRoll={name,value};let random=new Uint32Array(1);crypto.getRandomValues(random);let result=(random[0]%100)+1;$('#roll-caption').textContent=`D100 · ${name}`;$('#roll-number').textContent=String(result).padStart(2,'0');$('#roll-result').textContent=result===1?'大成功':result===100?'大失败':result<=Math.floor(value/5)?'极难成功':result<=Math.floor(value/2)?'困难成功':result<=value?'成功':'未成功';$('#roll-detail').textContent=`目标值 ${value} · 困难 ${Math.floor(value/2)} · 极难 ${Math.floor(value/5)}。${result<=value?'这次，命运站在你这边。':'故事还在继续，再试一种办法。'}`;if(!$('#roll-dialog').open)$('#roll-dialog').showModal();}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let action=b.dataset.action;
if(action==='variant')choose(Number(b.dataset.variant));
if(action==='next')choose(current%10+1);if(action==='previous')choose((current+8)%10+1);
if(action==='favorite'){s.favorites=s.favorites.includes(current)?s.favorites.filter(n=>n!==current):[...s.favorites,current];save();render();toast(s.favorites.includes(current)?'已收藏这个设计方向':'已取消收藏');}
if(action==='overview')overview();if(action==='close-dialog')b.closest('dialog')?.close();
if(action==='viewport'){let narrow=b.dataset.width==='narrow';$('#preview-viewport').classList.toggle('narrow',narrow);all('[data-action="viewport"]').forEach(x=>x.setAttribute('aria-pressed',x===b));}
if(action==='modules'){moduleRows();$('#modules-dialog').showModal();}
if(action==='open-builder')choose(10);
if(action==='move-module'){let order=b.closest('#demo-stage')?s.moduleOrder.filter(m=>s.enabledModules.includes(m)):s.moduleOrder;let position=order.indexOf(b.dataset.module),target=order[position+(b.dataset.direction==='up'?-1:1)];let i=s.moduleOrder.indexOf(b.dataset.module),next=s.moduleOrder.indexOf(target);if(i>=0&&next>=0&&next<s.moduleOrder.length){[s.moduleOrder[i],s.moduleOrder[next]]=[s.moduleOrder[next],s.moduleOrder[i]];save();render();moduleRows();}}
if(action==='resource'){let k=b.dataset.resource;s.resources[k]=Math.max(0,Math.min(s.maxResources[k],s.resources[k]+Number(b.dataset.delta)));updateResources();save();}
if(action==='roll'){let skill=b.dataset.index!==undefined?s.skills[Number(b.dataset.index)]:s.skills.find(x=>x.name===b.dataset.skill);roll(b.dataset.skill||'幸运检定',skill?skill.value:Number(b.dataset.value)||50);}
if(action==='roll-again')roll(lastRoll.name,lastRoll.value);
if(action==='gear'){let i=Number(b.dataset.gear);s.gear=s.gear.includes(i)?s.gear.filter(x=>x!==i):[...s.gear,i];save();render();}
if(action==='trait'){let t=b.dataset.trait;s.traits=s.traits.includes(t)?s.traits.filter(x=>x!==t):[...s.traits,t];save();render();}
if(action==='export'){let blob=new Blob([JSON.stringify({demo:'纸上冒险',variant:current,character:s,ruleNote:'COC7 simplified visual prototype; not a full rules engine.'},null,2)],{type:'application/json'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`paper-adventure-${current}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('角色数据已导出');}
if(action==='journey'){all('[data-journey-panel]').forEach(p=>p.hidden=p.dataset.journeyPanel!==b.dataset.step);all('[data-action="journey"]').forEach(x=>{x.setAttribute('aria-pressed',x.dataset.step===b.dataset.step);x.classList.toggle('active',x.dataset.step===b.dataset.step)});}
if(action==='tab'){all('[data-tab-panel]').forEach(p=>p.hidden=p.dataset.tabPanel!==b.dataset.target);all('[data-action="tab"]').forEach(x=>x.setAttribute('aria-selected',x===b));}
});
document.addEventListener('input',e=>{let el=e.target;if(el.dataset.field){let k=el.dataset.field;s[k]=k==='age'?Math.min(99,Math.max(15,Number(el.value)||15)):el.value;derived();save();}if(el.dataset.stat){let k=el.dataset.stat;let n=Number(el.value);if(el.value!==''&&Number.isFinite(n)){s.stats[k]=Math.max(1,Math.min(99,n));el.closest('.stat-cell')?.querySelectorAll('.stat-dots i').forEach((dot,i)=>dot.classList.toggle('filled',i<Math.round(s.stats[k]/10)));derived();save();}}if(el.dataset.skillIndex!==undefined){let i=Number(el.dataset.skillIndex);s.skills[i].value=Math.max(0,Math.min(99,Number(el.value)||0));let t=$(`[data-threshold="${i}"]`);if(t)t.textContent=`${Math.floor(s.skills[i].value/2)} / ${Math.floor(s.skills[i].value/5)}`;save();}if(el.classList.contains('skill-search')){let box=el.parentElement.parentElement;let q=el.value.trim().toLowerCase(),count=0;box.querySelectorAll('.skill-row').forEach(row=>{row.hidden=!row.dataset.skillName.toLowerCase().includes(q);if(!row.hidden)count++;});let empty=box.querySelector('.skill-empty');if(empty)empty.hidden=count>0;}});
document.addEventListener('change',e=>{let el=e.target;if(el.dataset.stat)el.value=s.stats[el.dataset.stat];if(el.dataset.field==='age')el.value=s.age;if(el.dataset.skillIndex!==undefined)el.value=s.skills[Number(el.dataset.skillIndex)].value;if(el.dataset.moduleToggle){let id=el.dataset.moduleToggle;s.enabledModules=el.checked?[...new Set([...s.enabledModules,id])]:s.enabledModules.filter(m=>m!==id);save();render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')all('dialog[open]').forEach(d=>d.close());if(e.altKey&&(e.key==='ArrowRight'||e.key==='ArrowLeft')){e.preventDefault();choose(e.key==='ArrowRight'?current%10+1:(current+8)%10+1);}});
render();save();window.PaperAdventure={getState:()=>structuredClone(s),getVariant:()=>current,variants:variants.map(v=>({id:v.id,name:v.name}))};
})();
